#include <stdio.h>
#include <stdlib.h>

void prime_factors(long n) {
    long i = 2;
    while (i * i <= n) {
        if (n % i != 0) {
            i++;
        } else {
            n /= i;
            printf("%ld", i);
            if (n > 1) {
                printf("^%ld", 1);
            }
            if (n > 1) {
                printf(" ");
            }
        }
    }
    if (n > 1) {
        printf("%ld", n);
    }
    printf("\n");
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long num = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (num < 0 || num > 1000000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    prime_factors(num);
    return 0;
}
